import json, hashlib, datetime as dt
from pathlib import Path
conv = Path(r'D:\claude\hades\hades-v2-memories\hades-v2\conversations')

def hid(s):
    return hashlib.sha256(str(s).encode()).hexdigest()[:12]
def utc(ts):
    try:
        return dt.datetime.fromtimestamp(float(ts), dt.timezone.utc).strftime('%Y-%m-%d')
    except Exception:
        return '?'

sessions = [json.loads(l) for l in (conv/'sessions.jsonl').open(encoding='utf-8')]
dms = [s for s in sessions if s.get('chat_type')=='dm']
want = {s['id'] for s in dms}
meta = {s['id']: s for s in dms}

counts = {sid: {'user':0,'assistant':0,'assistant_stop':0,'assistant_img':0,'tool':0,'assistant_tools':0,'user_chars':[], 'asst_chars':[]} for sid in want}

for shard in sorted(conv.glob('messages-*.jsonl')):
    for line in shard.open(encoding='utf-8'):
        row = json.loads(line)
        sid = row.get('session_id')
        if sid not in want:
            continue
        role = row.get('role')
        content = row.get('content') if isinstance(row.get('content'), str) else ''
        if role == 'user':
            counts[sid]['user'] += 1
            counts[sid]['user_chars'].append(len(content))
        elif role == 'assistant':
            counts[sid]['assistant'] += 1
            counts[sid]['asst_chars'].append(len(content))
            if row.get('finish_reason') == 'stop':
                counts[sid]['assistant_stop'] += 1
            if '[IMG:' in content:
