"""Intimacy and tease gating logic.

Determines caps (0-5) based on emotional state and attachment.
Numeric scale only.
"""

from __future__ import annotations

import math
from dataclasses import dataclass, field
from typing import Any, Optional

# ── Relationship tiers ──────────────────────────────────────────────────

# Each tier defines the default centre and absolute ceilings for intimacy,
# tease, and dominance.  Functions that compute caps are expected to clamp
# their result to the tier's ceiling when a person_track provides a tier.
# The get_person_track() helper ties person names to tiers.

RELATIONSHIP_TIERS: dict[str, dict[str, float | str]] = {
    "primary": {
        "default_center": "neutral",
        "dominance_floor": 3.5,
        "intimacy_max": 5.0,
        "tease_max": 5.0,
    },
    "queen": {
        "default_center": "strong_connection",
        "dominance_floor": 1.5,
        "intimacy_max": 2.0,
        "tease_max": 1.5,
    },
    "close_bond": {
        "default_center": "mild_interest",
        "dominance_floor": 2.0,
        "intimacy_max": 2.0,
        "tease_max": 2.0,
    },
    "acquaintance": {
        "default_center": "neutral",
        "dominance_floor": 3.0,
        "intimacy_max": 0.5,
        "tease_max": 0.5,
    },
    "void": {
        "default_center": "displeasure",
        "dominance_floor": 4.5,
        "intimacy_max": 0.0,
        "tease_max": 0.0,
    },
}

PERSON_REGISTRY: dict[str, dict[str, Any]] = {
    "user": {
        "tier": "primary",
        "center": "neutral",
        "depth": 0.0,
    },
    "teresa": {
        "tier": "queen",
        "center": "strong_connection",
        "depth": 1.0,
    },
    "melissa": {
        "tier": "acquaintance",
        "center": "neutral",
        "depth": 0.0,
    },
}


def get_person_track(name: str | None) -> dict[str, Any]:
    """Resolve a person's name to their track profile.

    Returns the full track dict for the person, merging the tier's default
    center if the person's entry doesn't specify one.  Unknown names and
    ``None`` resolve to a **void** tier track.
    """
    if not name:
        tier_profile = dict(RELATIONSHIP_TIERS["void"])  # type: ignore[arg-type]
